import heatLinks from './book-heat-topic-index.json';
import lightLinks from './book-light-topic-index.json';
import waterLinks from './book-water-topic-index.json';
import particleLinks from './book-particle-topic-index.json';
import mechanicsLinks from './book-mechanics-topic-index.json';
type BookLink={kind:'word'|'why';term:string;topic:string;connection:string};
const links:BookLink[]=[...[...measurementLinks,...heatLinks,...lightLinks,...waterLinks,...particleLinks].map(link=>({...link,kind:'word' as const})),...mechanicsLinks.map(link=>({...link,kind:link.kind as 'word'|'why'}))];
import {navigateHash} from './hash-route';

export default function BookMeasurementLinks({topicId}:{topicId:string}){
 const related=links.filter(link=>link.topic===topicId);
 if(!related.length)return null;
 return <section className="lab-knowledge-connections" data-book-measurement-links={topicId}><h3><BookOpen size={20}/> {related.some(link=>link.kind==='why')?'Mit passenden Wörtern und Fragen weiterdenken':'Mit passenden Wörtern weiterdenken'}</h3>{related.map(link=><div className="connection-card" key={link.kind==='word'?link.term:'why:'+link.term}><a className="knowledge-link" data-route-focus={'topic-'+(link.kind==='why'?'why':'word')+'-'+topicId+'-'+link.term} href={'#book/'+(link.kind==='why'?'why':'words')+'/'+encodeURIComponent(link.term)} onClick={event=>{event.preventDefault();navigateHash('book/'+(link.kind==='why'?'why':'words')+'/'+encodeURIComponent(link.term));}}><span>{link.term}</span><ArrowRight size={17}/></a><p>{link.connection}</p></div>)}</section>;
}

import {LearningDetails} from './learning-components';
import {navigateHash} from './hash-route';
import incomingLight from './book-light-word-link-index.json';
import incomingWater from './book-water-word-link-index.json';
import incomingParticle from './book-particle-word-link-index.json';
import incomingMechanics from './book-mechanics-word-link-index.json';

const incoming:Record<string,{term:string;reason:string}[]>={};
for(const pack of [incomingLight,incomingWater,incomingParticle,incomingMechanics])for(const [term,links]of Object.entries(pack))(incoming[term]??=[]).push(...links);

/** Small generated incoming edges keep existing words connected as a pack grows. */
export function BookRelatedWords({term}:{term:string}){
 const links=incoming[term];
 if(!links?.length)return null;
 return <LearningDetails className="book-related-words" summary="Verwandte Begriffe entdecken" data-book-related-words={term} data-history-disclosure={'book-related-words-'+term}>
  <ul>{links.map(link=><li key={link.term}><p>{link.reason}</p><a className="book-topic-link" href={'#book/words/'+encodeURIComponent(link.term)} data-route-focus={'book-word-related-'+term+'-'+link.term} onClick={event=>{event.preventDefault();navigateHash('book/words/'+encodeURIComponent(link.term));}}>Mit „{link.term}“ weiterdenken →</a></li>)}</ul>
 </LearningDetails>;
}

