 useEffect(()=>{if(lookup?.tab!=="why"||tab!=="why")return;const frame=requestAnimationFrame(()=>{const i=WHY_QUESTIONS.findIndex(([q])=>q===lookup.term),target=document.getElementById('why-entry-'+i) as HTMLDetailsElement|null;if(target){target.open=true;target.scrollIntoView({block:'center'});}});return()=>cancelAnimationFrame(frame);},[lookup,tab,intent]);
