 const selectedCountries=countries.map(countryPlace).filter(p=>p.capital&&(!term||searchScore(term,p.name,p.capital)>0));
 return <section className="knowledge-book"><p className="book-inventory">{GLOSSARY.length} Wörter · Warumfragen · eigene Notizen · zwei Atlanten</p><Tabs value={tab} onValueChange={v=>{onRead("");if(notesRoute)navigateHash("book");setView(previous=>({...previous,route:notesRoute?"book":route,tab:v,query:"",limit:24}));}}><div className="book-navigation"><button className="area-scroll" ref={previousRef} aria-label="Vorherige Buchbereiche anzeigen" onClick={()=>scroll(-1)}><ChevronLeft size={20} aria-hidden="true"/></button><TabsList ref={listRef} className="book-tabs" aria-label="Wissensbuch-Bereich" onFocusCapture={event=>{const target=(event.target as HTMLElement).closest<HTMLElement>('[role=tab]');if(target)reveal(target);}}><TabsTrigger value="words"><BookOpen size={17}/> Wörter</TabsTrigger><TabsTrigger value="why"><HelpCircle size={17}/> Warum?</TabsTrigger><TabsTrigger value="notes"><BookOpen size={17}/> Notizbuch</TabsTrigger><TabsTrigger value="nature"><Compass size={17}/> Naturatlas</TabsTrigger><TabsTrigger value="atlas"><Globe2 size={17}/> Kleiner Atlas</TabsTrigger></TabsList><button className="area-scroll" ref={nextRef} aria-label="Weitere Buchbereiche anzeigen" onClick={()=>scroll(1)}><ChevronRight size={20} aria-hidden="true"/></button></div><TabsContent value={tab}>{!["why","notes","nature"].includes(tab)&&<div className="book-search"><Search size={21}/><Input value={query} onChange={e=>{onRead("");set("query",e.target.value);set("limit",24);}} placeholder={tab==="words"?"Zum Beispiel: Wolke, Äquator, Lava …":"Suche ein Land oder eine Hauptstadt …"} aria-label={tab==="words"?"Wissenswörter durchsuchen":"Länderwissen durchsuchen"}/></div>}{tab==="words"?<><Tabs value={category} onValueChange={value=>set("category",value)}><details className="book-filter-panel" data-history-disclosure="book-word-filters"><summary>Wörter filtern{category!=="Alle"&&" · "+category}{letter!=="Alle"&&" · "+letter}</summary><TabsList className="word-categories" aria-label="